from rich.console import Console
import io

class ProxyFile(io.TextIOBase):
    def __init__(self, target):
        self.target = target

    @property
    def isatty(self):
        # Simulate a proxy where isatty is a property, not a callable
        return self.target.isatty()

def test_proxy_isatty():
    try:
        # Use a real file or sys.stdout to test
        import sys
        proxy = ProxyFile(sys.stdout)
        console = Console(file=proxy)
        print(f"Is ATTY: {console._is_atty()}")
    except TypeError as e:
        print(f"Caught expected TypeError: {e}")
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_proxy_isatty()

